D={
84001:("Escolhas sutis de tempo","O **passado contínuo** suaviza pedidos; o **past perfect contínuo** explica o pano de fundo.",[("{{I was wondering}} whether you might help.","Eu me perguntava se você poderia ajudar."),("He looked worn out; he {{had been working}} all night.","Ele parecia exausto; vinha trabalhando a noite toda."),("I {{was hoping}} you'd join us.","Eu esperava que você se juntasse a nós."),("They {{had been negotiating}} for weeks.","Negociavam havia semanas.")],"Qual suaviza um pedido?",["I was wondering if you could…","I wonder if you can…","I wondered you could…"],0,"Passado contínuo."),
84002:("Futuro no passado","**Would / was going to / was to** olham adiante a partir do passado.",[("He didn't know he {{would never return}}.","Ele não sabia que nunca voltaria."),("She {{was going to}} call, but forgot.","Ela ia ligar, mas esqueceu."),("He {{was to become}} a legend.","Ele viria a ser uma lenda."),("They {{were about to}} leave when it rang.","Estavam prestes a sair quando tocou.")],"“Was to become” indica…",["destino visto do passado","plano atual","hábito"],0,"Futuro no passado."),
84003:("Formas perfeitas avançadas","Particípio perfeito (*Having been warned*), infinitivo perfeito (*seems to have left*), **will have been -ing**.",[("{{Having been warned}}, he stayed home.","Tendo sido avisado, ele ficou em casa."),("She {{seems to have left}} already.","Parece que ela já saiu."),("By June, I {{will have been teaching}} for ten years.","Em junho, estarei lecionando há dez anos."),("{{Having finished}}, they celebrated.","Tendo terminado, comemoraram.")],"“Having been warned” indica…",["ação anterior passiva","ação futura","hábito"],0,"Anterior e passiva."),
950001:("bog down / boil down to","**Bog down** = atolar; **boil down to** = resumir-se a; **bottom out** = chegar ao fundo; **branch out** = diversificar.",[("The talks got {{bogged down}} in detail.","As negociações atolaram em detalhes."),("It all {{boils down to}} trust.","Tudo se resume a confiança."),("Prices have {{bottomed out}}.","Os preços chegaram ao fundo do poço."),("The firm {{branched out}} into software.","A empresa diversificou para software.")],"“Branch out” =",["diversificar","quebrar um galho","ramificar a árvore"],0,"Diversificar."),
84004:("Condicionais mistas","Passado afeta o presente: **If + past perfect, would + base**; presente afeta o passado: **If + past, would have + particípio**.",[("If I {{hadn't taken}} that job, I'd {{be}} elsewhere now.","Se eu não tivesse aceitado aquele emprego, estaria noutro lugar agora."),("If I {{were}} braver, I'd {{have spoken}} up.","Se eu fosse mais corajoso, teria falado."),("If she {{had studied}}, she {{would be}} a doctor.","Se ela tivesse estudado, seria médica."),("If he {{weren't}} so shy, he'd {{have asked}}.","Se ele não fosse tão tímido, teria perguntado.")],"“If I were braver, I'd have spoken” mistura…",["presente e passado","dois futuros","dois presentes"],0,"Mista."),
950002:("firm up / nail down","**Firm up** = consolidar; **lock down / nail down** = fechar de vez; **pin down** = identificar com exatidão.",[("Let's {{firm up}} the schedule.","Vamos consolidar o cronograma."),("We must {{nail down}} the details.","Precisamos fechar os detalhes."),("I can't {{pin down}} the cause.","Não consigo identificar a causa exata."),("They {{locked down}} the deal.","Eles fecharam o acordo.")],"“Pin down” =",["identificar com precisão","prender com alfinete","derrubar"],0,"Precisão."),
84005:("Subjuntivo formal","Depois de **insist, demand, recommend, require** e de adjetivos como **essential**: *that + sujeito + base*.",[("I insist that he {{be}} present.","Insisto que ele esteja presente."),("It is essential that she {{arrive}} early.","É essencial que ela chegue cedo."),("They demanded that the fee {{be}} waived.","Exigiram que a taxa fosse dispensada."),("We recommend that he {{not go}}.","Recomendamos que ele não vá.")],"Qual está certa?",["I insist that he is present.","I insist that he be present.","I insist that he will be present."],1,"Base."),
84006:("Gerúndio × infinitivo","O sentido muda: *I remember locking* (lembro que tranquei) × *Remember to lock* (não esqueça de trancar).",[("I {{remember locking}} the door.","Lembro de ter trancado a porta."),("{{Remember to lock}} the door.","Lembre-se de trancar a porta."),("He {{stopped to smoke}}.","Ele parou para fumar."),("He {{stopped smoking}}.","Ele parou de fumar.")],"“He stopped smoking” =",["largou o hábito","parou para fumar","fumou"],0,"Parou de."),
84007:("Orações participiais","Particípios comprimem a frase: *Not knowing what to say, she stayed silent. Written in haste, the note…*",[("{{Not knowing what to say}}, she stayed silent.","Sem saber o que dizer, ela ficou calada."),("{{Written in haste}}, the note was unclear.","Escrita às pressas, a nota era confusa."),("{{Having heard enough}}, he left.","Tendo ouvido o bastante, ele saiu."),("{{Seen from above}}, the city glows.","Vista de cima, a cidade brilha.")],"“Written in haste” é…",["particípio passado (passivo)","gerúndio ativo","infinitivo"],0,"Passivo."),
84008:("Sintagmas nominais complexos","Compacte ideias em substantivos: *The gradual accumulation of small changes drives evolution.*",[("{{The gradual accumulation of small changes}} drives evolution.","O acúmulo gradual de pequenas mudanças impulsiona a evolução."),("{{The sharp rise in food prices}} alarmed many.","A forte alta nos preços dos alimentos alarmou muitos."),("{{A growing sense of unease}} spread.","Um crescente sentimento de inquietação se espalhou."),("{{The need for reform}} is urgent.","A necessidade de reforma é urgente.")],"O objetivo é…",["compactar ideias","alongar","evitar substantivos"],0,"Compactar."),
950003:("beat the odds","**Beat the odds** = vencer apesar das chances; **burn the midnight oil**; **go the extra mile**; **hit the ground running**.",[("She {{beat the odds}} and won.","Ela venceu apesar das chances."),("We {{burned the midnight oil}} to finish.","Trabalhamos até tarde para terminar."),("He always {{goes the extra mile}}.","Ele sempre faz além do esperado."),("The new hire {{hit the ground running}}.","O novato começou a todo vapor.")],"“Hit the ground running” =",["começar com força","cair correndo","tropeçar"],0,"Começar com tudo."),
84009:("Nominalização","Verbo → substantivo para tom formal: *implement → implementation*, *reduce → reduction*, *deteriorate → deterioration*.",[("The {{implementation}} of the plan was slow.","A implementação do plano foi lenta."),("A sharp {{reduction}} in costs followed.","Seguiu-se uma forte redução de custos."),("The {{deterioration}} of relations worried us.","A deterioração das relações nos preocupou."),("Its {{adoption}} was swift.","Sua adoção foi rápida.")],"Substantivo de “reduce”:",["reduction","reducing","reduced"],0,"Reduction."),
950004:("vocabulário náutico","**Tack** (zigue-zague), **veer** (desviar), **jettison** (jogar ao mar), **scuttle** (afundar de propósito).",[("The boat {{tacked}} against the wind.","O barco fez bordos contra o vento."),("The ship {{veered}} off course.","O navio desviou da rota."),("They {{jettisoned}} the cargo.","Jogaram a carga ao mar."),("The crew {{scuttled}} the vessel.","A tripulação afundou o navio de propósito.")],"“Jettison” =",["descartar/jogar fora","jogar a vela","pescar"],0,"Descartar."),
84010:("Elipse e substituição","Omita o que o contexto informa: *She wanted to go; I didn't. He can swim, and so can I.*",[("She wanted to go; I {{didn't}}.","Ela queria ir; eu não."),("I'd love to, but I {{can't}}.","Adoraria, mas não posso."),("He can swim, and {{so can I}}.","Ele sabe nadar, e eu também."),("Do it if you {{want to}}.","Faça se quiser.")],"“So can I” evita repetir…",["o verbo inteiro","o sujeito","a preposição"],0,"Elipse."),
84011:("Coesão e referência","**The former / the latter**, **This, in turn, led to…** ligam ideias.",[("{{The former}} was cheaper, {{the latter}} lasted longer.","O primeiro era mais barato, o segundo durava mais."),("Prices rose. {{This}}, in turn, led to protests.","Os preços subiram. Isso, por sua vez, levou a protestos."),("{{Such}} measures are unpopular.","Tais medidas são impopulares."),("{{That said}}, they work.","Dito isso, funcionam.")],"“The latter” =",["o segundo de dois","o último de muitos","o anterior"],0,"Segundo."),
84012:("Modalidade avançada","Suavize com **would seem to, appear to, tend to, is likely to**.",[("Such a policy {{would seem to}} offer benefits.","Tal política parece oferecer benefícios."),("The results {{appear to}} confirm it.","Os resultados parecem confirmar."),("Prices {{tend to}} fall.","Os preços tendem a cair."),("It {{is likely to}} work.","É provável que funcione.")],"Qual é mais cauteloso?",["It proves it.","It would seem to prove it.","It is it."],1,"Would seem to."),
84013:("Concessão","**Try as he might…, Much as I admire her…, However hard he tried…**",[("{{Try as he might}}, he couldn't forget.","Por mais que tentasse, ele não conseguia esquecer."),("{{Much as I admire her}}, I disagree.","Por mais que a admire, discordo."),("{{However hard he tried}}, he failed.","Por mais que tentasse, ele falhou."),("{{Strange as it may seem}}, it's true.","Por estranho que pareça, é verdade.")],"“Much as I admire her” =",["embora eu a admire muito","porque a admiro","quanto mais admiro"],0,"Concessão."),
950005:("pull the plug","**Pull the plug** = cancelar de vez; **pull the trigger** = decidir; **mothball** = engavetar temporariamente; **shelve** = engavetar.",[("They {{pulled the plug}} on the project.","Eles cancelaram o projeto de vez."),("It's time to {{pull the trigger}}.","É hora de tomar a decisão final."),("The plan was {{mothballed}}.","O plano foi engavetado por ora."),("They {{shelved}} the idea.","Engavetaram a ideia.")],"“Pull the trigger” (decisão) =",["decidir de vez","puxar o gatilho","atirar"],0,"Decisão."),
84014:("Contraste e oposição","**Whereas / while** contrastam; entre frases: **By contrast, On the other hand**.",[("{{Whereas}} he sought peace, she sought change.","Enquanto ele buscava paz, ela buscava mudança."),("{{By contrast}}, the north is dry.","Em contraste, o norte é seco."),("{{On the other hand}}, it's costly.","Por outro lado, é caro."),("{{While}} some agree, others don't.","Enquanto alguns concordam, outros não.")],"“By contrast” introduz…",["contraste","exemplo","causa"],0,"Contraste."),
950006:("break through / crack down","**Break through** = atravessar barreira; **cling to** = agarrar-se; **crack down** = endurecer; **crop up** = surgir.",[("Rescuers {{broke through}} the ice.","Os socorristas romperam o gelo."),("He {{clung to}} the ledge.","Ele se agarrou à beirada."),("Police {{cracked down}} on crime.","A polícia endureceu contra o crime."),("Problems {{cropped up}}.","Problemas surgiram.")],"“Crop up” =",["surgir","cortar","plantar"],0,"Surgir."),
84015:("Propósito e resultado","**So as to, in order to, so that** (propósito); **such that** (resultado).",[("He spoke slowly {{so as to}} be understood.","Ele falou devagar para ser entendido."),("She left early {{so that}} she wouldn't be late.","Ela saiu cedo para não se atrasar."),("It was {{such a mess}} that we left.","Era uma bagunça tal que saímos."),("They saved {{in order to}} travel.","Economizaram para viajar.")],"Qual expressa propósito?",["so as to","such that","as a result"],0,"So as to."),
84016:("Tempo na narrativa","**By the time…, As soon as … had…, No sooner … than…**",[("{{By the time}} we arrived, it had stopped.","Quando chegamos, já tinha parado."),("{{As soon as}} he had left, she cried.","Assim que ele saiu, ela chorou."),("{{No sooner had}} I sat {{than}} it rang.","Mal me sentei, tocou."),("{{Once}} the rain stopped, we went out.","Assim que a chuva parou, saímos.")],"“By the time” pede…",["past perfect na oração principal","presente","futuro"],0,"Anterioridade."),
84017:("Comparação avançada","**The more …, the less …**; intensifique com **far, considerably**.",[("{{The more}} he read, {{the less}} he understood.","Quanto mais lia, menos entendia."),("It's {{far}} more complicated.","É muito mais complicado."),("{{Considerably}} fewer people came.","Muito menos gente veio."),("It's {{nowhere near}} as good.","Nem de longe é tão bom.")],"“Far more” =",["muito mais","longe mais","mais distante"],0,"Muito mais."),
950007:("mount a challenge","**Mount a challenge**, **launch a campaign** (começar); **spearhead** (liderar); **orchestrate** (organizar).",[("They {{mounted a challenge}} to the law.","Eles contestaram a lei."),("She {{launched a campaign}}.","Ela lançou uma campanha."),("He {{spearheaded}} the reform.","Ele liderou a reforma."),("The event was {{orchestrated}} by the team.","O evento foi orquestrado pela equipe.")],"“Spearhead” =",["liderar","atacar com lança","seguir"],0,"Liderar."),
84018:("Quantificadores avançados","**A fair number of, a great deal of, the vast majority of**; negativo: *few, scant*.",[("{{A fair number of}} people agreed.","Um bom número de pessoas concordou."),("{{A great deal of}} effort was needed.","Foi preciso muito esforço."),("{{The vast majority of}} voters supported it.","A grande maioria dos eleitores apoiou."),("{{Scant}} evidence exists.","Há pouca evidência.")],"“Scant” =",["escasso","largo","vasto"],0,"Escasso."),
84019:("Preposições fixas","**In view of, on behalf of, in accordance with, with regard to**.",[("{{In view of}} the delay, we left.","Diante do atraso, partimos."),("I speak {{on behalf of}} the team.","Falo em nome da equipe."),("{{In accordance with}} the rules.","Em conformidade com as regras."),("{{With regard to}} your request…","Com relação ao seu pedido…")],"“On behalf of” =",["em nome de","a favor de","ao lado de"],0,"Em nome de."),
950008:("make headway","**Make headway** = avançar; **pay dividends** = render frutos; **strike a deal**; **reach a consensus**.",[("We're {{making headway}}.","Estamos avançando."),("The training {{paid dividends}}.","O treinamento rendeu frutos."),("They {{struck a deal}}.","Fecharam um acordo."),("The panel {{reached a consensus}}.","O painel chegou a um consenso.")],"“Pay dividends” =",["render bons frutos","pagar lucros","dever"],0,"Compensar."),
84020:("Preposições dependentes","**Accustomed to, fond of, keen on, blame … for, insist on**; depois de *to*: -ing.",[("He's {{accustomed to}} working late.","Ele está acostumado a trabalhar até tarde."),("She's {{fond of}} jazz.","Ela gosta de jazz."),("They {{blame}} him {{for}} the loss.","Culpam-no pela perda."),("I {{insist on}} paying.","Faço questão de pagar.")],"Qual está certa?",["accustomed to work","accustomed to working","accustomed working"],1,"To + -ing."),
84021:("Artigos no abstrato","Conceitos gerais: **sem artigo**; *the* quando especificado.",[("{{Happiness}} is not the same as pleasure.","A felicidade não é o mesmo que prazer."),("{{Freedom}} requires courage.","A liberdade exige coragem."),("{{The freedom}} we enjoy was hard-won.","A liberdade que desfrutamos foi conquistada com esforço."),("{{Life}} is short.","A vida é curta.")],"Quando usar “the”?",["quando o conceito é especificado","sempre","nunca"],0,"Especificado."),
950009:("insofar as","**Insofar as / in so far as** = na medida em que; **inasmuch as** = dado que; **to the extent that**.",[("{{Insofar as}} I can tell, it works.","Na medida em que posso avaliar, funciona."),("{{Inasmuch as}} he lied, he's guilty.","Dado que mentiu, é culpado."),("{{To the extent that}} it helps, use it.","Na medida em que ajude, use."),("It matters {{in so far as}} it affects us.","Importa na medida em que nos afeta.")],"“To the extent that” mede…",["o grau","o tempo","o lugar"],0,"Grau."),
84022:("Contáveis e incontáveis","**Advice, news, information, luggage, furniture** são incontáveis: *a piece of advice*.",[("Let me give you {{a piece of advice}}.","Deixe-me dar um conselho."),("{{The news}} is good.","A notícia é boa."),("We lost our {{luggage}}.","Perdemos a bagagem."),("An {{item of}} furniture arrived.","Chegou um móvel.")],"Qual está certa?",["an advice","a piece of advice","advices"],1,"Incontável."),
84023:("Posição dos advérbios","Frequência: **antes do verbo principal**, **depois do auxiliar**: *She almost never complains.*",[("She {{almost never}} complains.","Ela quase nunca reclama."),("She has {{seldom}} complained.","Ela raramente reclamou."),("He is {{always}} late.","Ele está sempre atrasado."),("They {{rarely}} agree.","Eles raramente concordam.")],"Qual está certa?",["She has never been late.","She never has been late.","Never she has late."],0,"Depois do auxiliar."),
84024:("Intensificadores","**Utterly / totally / absolutely** com extremos; **very / quite** com graduáveis.",[("It was {{utterly}} absurd.","Foi totalmente absurdo."),("It's {{absolutely}} perfect.","É absolutamente perfeito."),("He is {{highly}} skilled.","Ele é altamente qualificado."),("It's {{fairly}} common.","É bastante comum.")],"Qual combina com “absurd”?",["utterly","very","fairly"],0,"Extremo."),
84025:("Tags e retóricas","A tag inverte auxiliar e polaridade: *You wouldn't mind, would you?* Após *Let's*: **shall we**.",[("You wouldn't mind, {{would you}}?","Você não se importaria, não é?"),("She is leaving, {{isn't she}}?","Ela está saindo, não está?"),("Let's go, {{shall we}}?","Vamos, está bem?"),("{{Who knows}}?","Quem sabe?")],"“Let's go, ___?”",["shall we","will we","let we"],0,"Shall we."),
950010:("dawn on","**Dawn on** = ocorrer de repente; **doze off** = cochilar; **drag on** = arrastar-se; **draw up** = elaborar.",[("It finally {{dawned on}} me.","Finalmente me ocorreu."),("I {{dozed off}} in the meeting.","Cochilei na reunião."),("The talks {{dragged on}}.","As conversas se arrastaram."),("They {{drew up}} a contract.","Elaboraram um contrato.")],"“Draw up” =",["elaborar","desenhar para cima","retirar"],0,"Elaborar."),
84026:("Verbos de relato com nuance","**Insinuated, conceded, alleged, maintained** mostram a atitude.",[("She {{insinuated}} that he lied.","Ela insinuou que ele mentiu."),("He {{conceded}} that he was wrong.","Ele admitiu que estava errado."),("They {{alleged}} that the deal was rigged.","Alegaram que o acordo era fraudado."),("He {{maintained}} his innocence.","Ele sustentou sua inocência.")],"“Concede” =",["admitir","conceder dinheiro","concentrar"],0,"Admitir."),
950011:("stack up / live up to","**Stack up** = comparar-se; **live up to** = corresponder; **come up short** = ficar aquém; **rise to the occasion**.",[("How does it {{stack up}} against rivals?","Como se compara aos rivais?"),("It didn't {{live up to}} expectations.","Não correspondeu às expectativas."),("We {{came up short}}.","Ficamos aquém."),("She {{rose to the occasion}}.","Ela esteve à altura da ocasião.")],"“Live up to” =",["corresponder a","viver acima","subir"],0,"Corresponder."),
84027:("Passiva acadêmica","**It has been suggested that… It is thought to be…** tiram o foco de quem age.",[("{{It has been suggested that}} time bends.","Sugeriu-se que o tempo se curva."),("It {{is thought to be}} harmless.","Pensa-se que seja inofensivo."),("The results {{were interpreted}} cautiously.","Os resultados foram interpretados com cautela."),("It {{is widely believed}}.","Acredita-se amplamente.")],"Por que a passiva acadêmica?",["tira o foco do agente","mostra emoção","dá ordens"],0,"Impessoal."),
84028:("do enfático e clivadas","**Do / does / did** + base enfatiza; **It was … who / that** destaca um elemento.",[("I {{do apologize}}.","Eu realmente peço desculpas."),("She {{did warn}} us.","Ela de fato nos avisou."),("{{It was Tom who}} called.","Foi o Tom quem ligou."),("{{It was last year that}} we met.","Foi no ano passado que nos conhecemos.")],"“It was Tom who called” destaca…",["Tom","o telefonema","o ano"],0,"Tom."),
84029:("Revisão avançada","**Condicional invertida** (*Had she known*), **passiva** (*It is said to be*), **participial** (*Having left*).",[("{{Had she known}}, she'd have acted.","Se soubesse, teria agido."),("It {{is said to be}} true.","Diz-se que é verdade."),("{{Having left early}}, he missed it.","Tendo saído cedo, ele perdeu."),("{{Rarely do we}} see this.","Raramente vemos isso.")],"“Had she known” =",["if she had known","if she knew","if she knows"],0,"Inversão."),
84030:("Verbos de fala precisos","Troque *said*: **mutter, whisper, murmur** (baixo); **stammer, falter** (hesitante); **snap, bark, declare** (forte).",[("He {{muttered}} an apology.","Ele resmungou um pedido de desculpas."),("She {{whispered}} a secret.","Ela sussurrou um segredo."),("The sergeant {{barked}} orders.","O sargento berrou ordens."),("He {{stammered}} his reply.","Ele gaguejou a resposta.")],"“Bark” (voz) =",["berrar ordens","latir","descascar"],0,"Berrar."),
950012:("inversão após negativos","**Never have I, rarely does, little did, under no circumstances**: auxiliar antes do sujeito.",[("{{Never have I}} seen such beauty.","Nunca vi tamanha beleza."),("{{Rarely does he}} complain.","Raramente ele reclama."),("{{Little did we know}} what would happen.","Pouco sabíamos o que aconteceria."),("{{Under no circumstances should you}} enter.","Em hipótese alguma você deve entrar.")],"Qual está certa?",["Never I have seen it.","Never have I seen it.","Never saw I it."],1,"Inversão."),
950013:("down to the wire","**Down to the wire** = decidido no último instante; **throw in the towel** = desistir; **tip the scales**; **raise the bar**.",[("It went {{down to the wire}}.","Foi decidido no último instante."),("He refused to {{throw in the towel}}.","Ele se recusou a desistir."),("That {{tipped the scales}}.","Isso fez pender a balança."),("She {{raised the bar}}.","Ela elevou o nível.")],"“Raise the bar” =",["elevar o padrão","levantar a barra","fazer barulho"],0,"Elevar."),
84031:("Verbos de movimento precisos","O verbo já diz *como*: **trudge, plod** (cansado), **stroll, amble** (relaxado), **dash, sprint** (rápido).",[("We {{trudged}} through the snow.","Arrastamo-nos pela neve."),("They {{strolled}} along the beach.","Eles passearam pela praia."),("She {{dashed}} to the door.","Ela correu até a porta."),("He {{staggered}} home.","Ele cambaleou até em casa.")],"“Amble” =",["andar sem pressa","andar rápido","tropeçar"],0,"Relaxado."),
84032:("Tons de olhar","**Glance, glimpse, peek** (rápido); **gaze, stare** (longo); **glare** (hostil); **scan, study** (atento).",[("She {{glanced}} at her watch.","Ela deu uma olhada no relógio."),("He {{gazed}} at the stars.","Ele contemplou as estrelas."),("She {{glared}} at him.","Ela o fuzilou com o olhar."),("I {{scanned}} the list.","Passei os olhos pela lista.")],"“Glare” =",["olhar hostil","brilho","olhar de relance"],0,"Hostil."),
84033:("Pensar e acreditar","Graus de certeza: **I reckon, I suppose** (palpite); **I presume**; **I firmly believe**.",[("{{I reckon}} it's late.","Acho que é tarde."),("{{I presume}} you've heard.","Presumo que você tenha ouvido."),("{{I firmly believe}} in justice.","Acredito firmemente na justiça."),("{{I suppose}} you're right.","Suponho que você tenha razão.")],"Qual é a mais firme?",["I reckon","I presume","I firmly believe"],2,"Convicção."),
84034:("Emoção com profundidade","Além de happy/sad: **bewildered, apprehensive, elated, wistful**.",[("She was {{bewildered}} by the news.","Ela ficou perplexa com a notícia."),("He felt {{apprehensive}}.","Ele se sentiu apreensivo."),("They were {{elated}}.","Estavam eufóricos."),("A {{wistful}} smile.","Um sorriso saudoso.")],"“Elated” =",["eufórico","exausto","elegante"],0,"Eufórico."),
}
